def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, tags=tags or [],
        created_at=created_at or NOW - timedelta(hours=id),
    )


@pytest.fixture
def tasks():
    return [
        _task(1, "Alpha", priority=TaskPriority.HIGH, tags=[Tag("work")]),
        _task(2, "Beta", status=TaskStatus.DONE, tags=[Tag("home")]),
        _task(3, "Gamma", due_at=NOW - timedelta(hours=1), tags=[Tag("work"), Tag("urgent")]),
        _task(4, "Delta", due_at=NOW + timedelta(hours=1)),
        _task(5, "Epsilon", priority=TaskPriority.LOW),
    ]


class TestFilters:
    def test_no_filter(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 5

    def test_status_filter_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert all(t.status == TaskStatus.PENDING for t in page.items)
        assert page.total == 4

    def test_status_filter_done(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].title == "Beta"

    def test_tag_filter(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="work"), NOW)
        assert page.total == 2

    def test_search_filter(self, tasks):
        page = apply_query(tasks, TaskQuery(search="alph"), NOW)
        assert page.total == 1
        assert page.items[0].title == "Alpha"

    def test_search_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="BETA"), NOW)
        assert page.total == 1

    def test_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].title == "Gamma"

    def test_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        # All except Gamma (overdue) should be included
        assert page.total == 4

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, tag="work"), NOW)
        assert page.total == 2


